import{_ as t,o as h,c as i,a2 as a}from"./chunks/framework.BBd5PKnH.js";const s=JSON.parse('{"title":"Giải thích dễ hiểu về TCP vs UDP","description":"Lấy cảm hứng từ bài viết hay ho của Naman Sisodia trên Medium :v","frontmatter":{"title":"Giải thích dễ hiểu về TCP vs UDP","description":"Lấy cảm hứng từ bài viết hay ho của Naman Sisodia trên Medium :v","date":"2026-06-06T00:00:00.000Z"},"headers":[],"relativePath":"notes/giai-thich-de-hieu-ve-tcp-udp-http-va-websocket.md","filePath":"notes/giai-thich-de-hieu-ve-tcp-udp-http-va-websocket.md"}'),e={name:"notes/giai-thich-de-hieu-ve-tcp-udp-http-va-websocket.md"};function c(o,n,r,g,l,u){return h(),i("div",null,[...n[0]||(n[0]=[a('<blockquote><p><strong>Bài viết này lấy cảm hứng từ bài viết hay ho của Naman Sisodia trên Medium:</strong> <a href="https://any-one-can-code.medium.com/understanding-tcp-udp-http-and-websocket-concepts-part-1-499f9f751c54" target="_blank" rel="noreferrer">Understanding TCP, UDP, HTTP, And WebSocket Concepts PART - 1</a>. Mình đọc bài này và thấy cách giải thích khá là rõ ràng, dễ hiểu, ko bị quá ngộp các thuật ngữ technical, nên quyết định viết lại bằng tiếng Việt, mở rộng thêm phần HTTP và WebSocket để cho trọn bộ. Mọi công nhận xứng đáng đều thuộc về tác giả gốc! ⚠️ Ảnh thiếu: <strong>1_GEUhDCOVJVC1dGGBmFcg1Q (1).jpg</strong> (không có trong dữ liệu export, cần upload lại thủ công)</p></blockquote><h2 id="_1-udp" tabindex="-1">1. UDP <a class="header-anchor" href="#_1-udp" aria-label="Permalink to &quot;1. UDP&quot;">​</a></h2><h3 id="udp-la-gi" tabindex="-1">UDP là gì? <a class="header-anchor" href="#udp-la-gi" aria-label="Permalink to &quot;UDP là gì?&quot;">​</a></h3><p>UDP (User Datagram Protocol) là giao thức truyền dữ liệu theo cơ chế không cần kết nối và không đảm bảo (connectionless và unreliable). Nó sẽ cứ thế spam data tới đích mà không cần biết người nhận có đang sẵn sàng, có nhận được hay không, và cũng không yêu cầu phản hồi từ phía nhận.</p><h3 id="cau-chuyen-cua-server-va-client-voi-udp" tabindex="-1">Câu chuyện của Server và Client với UDP <a class="header-anchor" href="#cau-chuyen-cua-server-va-client-voi-udp" aria-label="Permalink to &quot;Câu chuyện của Server và Client với UDP&quot;">​</a></h3><p>Ví dụ Server muốn nhắn cho Client câu: <em>&quot;Mày ổn không?&quot;</em> Server chuyển câu đó thành các <strong>gói tin (packets)</strong> — mỗi gói tin chứa một mảnh dữ liệu nhỏ — rồi gửi thẳng tới client, không biết là client có sẵn sàng nhận kết nối hay không.</p><p><strong>Happy case:</strong> Client nhận đủ tất cả các gói tin, đọc được câu hoàn chỉnh.</p><blockquote><p>⚠️ Ảnh thiếu: <strong>udp-happy.png</strong> (không có trong dữ liệu export, cần upload lại thủ công)</p></blockquote><p><strong>Unhappy case 1 — Mất gói tin:</strong></p><blockquote><p>⚠️ Ảnh thiếu: <strong>udp-sad1.png</strong> (không có trong dữ liệu export, cần upload lại thủ công)</p></blockquote><p><strong>Unhappy case 2 — Nhận lung tung thứ tự:</strong></p><blockquote><p>⚠️ Ảnh thiếu: <strong>udp-sad2.png</strong> (không có trong dữ liệu export, cần upload lại thủ công)</p></blockquote><p>Và Server? Server không hề biết Client nhận được gì. <strong>Server đã gửi xong và quên luôn.</strong></p><h3 id="vay-thi-udp-co-ich-gi" tabindex="-1">Vậy thì UDP có ích gì? <a class="header-anchor" href="#vay-thi-udp-co-ich-gi" aria-label="Permalink to &quot;Vậy thì UDP có ích gì?&quot;">​</a></h3><p>Nghe có vẻ ko ổn lắm nhưng UDP lại cực kỳ hữu ích vì một lý do đơn giản: <strong>tốc độ</strong>. Vì không phải lo lắng về việc xác nhận, kết nối, hay thứ tự gói tin — UDP truyền data rất nhanh. UDP = nhanh + không đảm bảo. Dùng khi bạn <em>có thể chấp nhận mất dữ liệu</em>.</p><p>UDP được dùng ở đâu?</p><ul><li>Game online/multiplayer</li><li>Video streaming / YouTube</li><li>VoIP (gọi điện qua internet)</li><li>DNS</li></ul><h2 id="_2-tcp" tabindex="-1">2. TCP <a class="header-anchor" href="#_2-tcp" aria-label="Permalink to &quot;2. TCP&quot;">​</a></h2><h3 id="tcp-la-gi" tabindex="-1">TCP là gì? <a class="header-anchor" href="#tcp-la-gi" aria-label="Permalink to &quot;TCP là gì?&quot;">​</a></h3><p>TCP (Transmission Control Protocol) là giao thức <strong>hướng kết nối</strong> (connection-oriented). Trước khi truyền data, Server và Client phải kết nối với nhau đã. Sau đó mọi gói tin đều được đánh số, xác nhận, và nếu mất thì gửi lại.</p><h3 id="three-way-handshake" tabindex="-1">Three-Way Handshake <a class="header-anchor" href="#three-way-handshake" aria-label="Permalink to &quot;Three-Way Handshake&quot;">​</a></h3><blockquote><p>⚠️ Ảnh thiếu: <strong>Screenshot 2026-06-06 at 18.56.13.png</strong> (không có trong dữ liệu export, cần upload lại thủ công)</p></blockquote><p>Đây là bước khởi động bắt buộc của TCP. Nghe phức tạp nhưng thực ra rất đơn giản:</p><p><strong>Bước 1 — SYN:</strong> Client nhắn Server: <em>&quot;Ê Server, tao muốn nói chuyện. Số của tao là 100 nha.&quot;</em></p><p><strong>Bước 2 — SYN-ACK:</strong> Server trả lời: <em>&quot;Tao nhận được rồi (100+1=101). Và số của tao là 500 nha.&quot;</em></p><p><strong>Bước 3 — ACK:</strong> Client xác nhận: <em>&quot;Tao nhận được số của mày rồi (500+1=501). Bắt đầu thôi!&quot;</em></p><p>Cả hai bây giờ đã <strong>xác nhận lẫn nhau</strong> — ai cũng biết đối phương đang online và sẵn sàng kết nối.</p><h3 id="nhuoc-điem-cua-tcp" tabindex="-1">Nhược điểm của TCP? <a class="header-anchor" href="#nhuoc-điem-cua-tcp" aria-label="Permalink to &quot;Nhược điểm của TCP?&quot;">​</a></h3><ul><li><strong>Chậm hơn UDP</strong> vì phải làm nhiều thứ hơn.</li><li><strong>Không phù hợp để broadcast</strong> — Nếu Server muốn gửi data cho 1 triệu người, phải tạo 1 triệu kết nối riêng.</li></ul><h3 id="tcp-dung-o-đau" tabindex="-1">TCP dùng ở đâu? <a class="header-anchor" href="#tcp-dung-o-đau" aria-label="Permalink to &quot;TCP dùng ở đâu?&quot;">​</a></h3><ul><li>Web (HTTP/HTTPS)</li><li>WebSocket</li><li>Email (SMTP, IMAP)</li><li>Truyền file (FTP)</li><li>SSH Không cần dùng tool gì cho cái này — đây là đoạn dịch:</li></ul><p><strong>UDP hay TCP — cái nào tốt hơn?</strong></p><p>Thực ra không có cái nào tốt hơn giữa UDP và TCP cả. Cả hai đều phù hợp với những use case khác nhau. Không có giao thức hoàn hảo nào tồn tại — hay sẽ tồn tại — mà không có giới hạn. UDP phù hợp với các ứng dụng real-time, hạn chế độ trễ, và việc mất hoặc xáo trộn thông tin vẫn có thể chấp nhận được. TCP thì ngược lại — nó đảm bảo dữ liệu được truyền đi chính xác, nên người dùng không cần lo lắng gì về dữ liệu. Bonus cho quả meme:</p><blockquote><p>⚠️ Ảnh thiếu: <strong>1_vjQxkIN0ncEIFKngYiaDPA.jpg</strong> (không có trong dữ liệu export, cần upload lại thủ công)</p></blockquote>',34)])])}const d=t(e,[["render",c]]);export{s as __pageData,d as default};
